/bin/bash -lc "python - <<'PY'
import urllib.request
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://platform.openai.com/docs/guides/your-data']:
 try:
  s=urllib.request.urlopen(url, timeout=25).read().decode()
  from html import unescape
  import re
  s=unescape(re.sub('<["'^>]+>'"', ' ', s))
  terms=['store','abuse monitoring','30 days','input','model']
  print('SOURCE',url)
  for term in terms:
   m=re.search(r'.{0,150}\\b'+term+r'\\b.{0,300}',s,re.I)
   if m: print(m.group())
 except Exception as e: print(type(e).__name__,str(e))
PY"

