/bin/bash -lc "python -B - <<'PY'
import io, json, sys, urllib.error
from unittest.mock import patch
sys.path.insert(0, '/workspace')
from openai_client import OpenAIClient, OpenAIError, _NoRedirect
c = OpenAIClient('test-key')
body = {'status':'completed','output':[{'type':'message','content':[{'type':'output_text','text':'Hello '},{'type':'output_text','text':'world'}]}]}
with patch.object(c._opener, 'open', return_value=io.BytesIO(json.dumps(body).encode())) as send:
 assert c.generate('private synthetic prompt',model='test-model') == 'Hello world'
 req = send.call_args.args[0]
 assert req.full_url == 'https://api.openai.com/v1/responses'
 assert json.loads(req.data)['store'] is False
 assert req.get_header('Authorization') == 'Bearer test-key'
for error in [urllib.error.HTTPError('https://api.openai.com',401,'secret',{},io.BytesIO(b'secret')), urllib.error.URLError('secret')]:
 with patch.object(c._opener,'open',side_effect=error):
  try: c.generate('synthetic',model='test-model')
  except OpenAIError as e: assert 'secret' not in str(e)
  else: raise AssertionError('Expected sanitized failure')
with patch.object(c._opener,'open',return_value=io.BytesIO(b'not json')):
 try: c.create_response('synthetic',model='test-model')
 except OpenAIError: pass
 else: raise AssertionError('Expected invalid JSON failure')
with patch.object(c,'create_response',return_value={'status':'incomplete'}):
 try: c.generate('synthetic',model='test-model')
 except OpenAIError: pass
 else: raise AssertionError('Expected incomplete failure')
assert _NoRedirect().redirect_request(None,None,302,'',{},'https://example.com') is None
print('Passed mocked checks: payload, text extraction, HTTP/network errors, invalid JSON, incomplete response, redirect refusal.')
PY"

